import re
s=open('unpacked/word/document.xml',encoding='utf-8').read()
body_start=s.index('<w:body>')+len('<w:body>')
tag_re=re.compile(r'<(/?)(w:[A-Za-z]+)([^>]*?)(/?)>')
i=body_start; depth=0; start=None; cur=None; blocks=[]
while i<len(s):
    m=tag_re.search(s,i)
    if not m: break
    closing,name,attrs,selfclose=m.group(1),m.group(2),m.group(3),m.group(4)
    if not closing and not selfclose:
        if depth==0: start=m.start(); cur=name
        depth+=1
    elif closing:
        depth-=1
        if depth==0: blocks.append((cur,start,m.end()))
    else:
        if depth==0: blocks.append((name,m.start(),m.end()))
    i=m.end()

for n in range(12,28):
    t,a,b=blocks[n]
    blk=s[a:b]
    # list <w:t> texts containing patient
    for mt in re.finditer(r'<w:t(?: [^>]*)?>(.*?)</w:t>', blk):
        txt=mt.group(1)
        if re.search(r'[Pp]atient', txt):
            print(n, repr(txt[:300]))
            print('---')
